// Bodies of `/robots.txt` and `/sitemap.xml` (spec §7 "Sitemap").

/** robots.txt: catalogue crawlable, admin area and admin API not. */
export function robotsTxt(origin: string): string {
  return [
    'User-agent: *',
    'Allow: /',
    'Disallow: /admin',
    'Disallow: /*/admin',
    'Disallow: /api/admin',
    '',
    `Sitemap: ${origin.replace(/\/$/, '')}/sitemap.xml`,
    '',
  ].join('\n');
}

/** Path of the sitemap generated by the API from the published courses. */
export const SITEMAP_UPSTREAM_PATH = '/api/public/v1/sitemap.xml';
